                            "values and uncertainty to be None"
                        )
                elif value_cell is None or uncertainty_cell is None:
                    raise ValueError(
                        f"{where}: non-missing status at ({t}, {i}, {j}) requires "
                        "numeric values and uncertainty"
                    )


