        stack = [seed]
        visited.add(seed)
        component: list[tuple[int, int, int]] = []
        while stack:
            t, i, j = stack.pop()
            component.append((t, i, j))

            neighbours = (
                (t, i - 1, j),
                (t, i + 1, j),
                (t, i, j - 1),
                (t, i, j + 1),
                (t - 1, i, j),
                (t + 1, i, j),
